80	// Parses a raw manifest object and verifies every declared document file's
81	// bytes. Returns normalized, code-point-sorted entries carrying verified
82	// bodies, plus the manifest's bound snapshot checksum. Pure: never touches
83	// the file system.
84	export function parsePackage(manifestRaw, fileBytes) {
85	  if (!manifestRaw || typeof manifestRaw !== 'object' || Array.isArray(manifestRaw)) {
86	    throw invalidMarkdown('manifest must be a JSON object');
87	  }
88	  if (!sameKeys(manifestRaw, MANIFEST_KEYS)) {
89	    throw invalidMarkdown('manifest must contain exactly version, documents, and checksum');
90	  }
91	  const { version, documents, checksum } = manifestRaw;
92	  if (typeof version !== 'number' || version !== PACKAGE_VERSION) {
93	    throw invalidMarkdown(`unsupported manifest version: ${String(version)}`);
94	  }
95	  if (!Array.isArray(documents)) throw invalidMarkdown('manifest documents must be an array');
96	  if (typeof checksum !== 'string' || !HEX_SHA256.test(checksum)) {
97	    throw invalidMarkdown('manifest checksum must be a lowercase hex SHA-256');
98	  }
99	
100	  const seenIds = new Set();
101	  const entries = [];
102	  documents.forEach((raw, index) => {
103	    const location = `documents[${index}]`;
104	    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
105	      throw invalidMarkdown(`${location} must be an object`);
106	    }
107	    if (!sameKeys(raw, ENTRY_KEYS)) {
108	      throw invalidMarkdown(`${location} must contain exactly id, title, tags, file, and sha256`);
109	    }
110	    const { id, title, tags, file, sha256 } = raw;
111	    if (typeof id !== 'string') throw invalidMarkdown(`${location}.id must be a string`);
112	    if (typeof title !== 'string') throw invalidMarkdown(`${location}.title must be a string`);
113	    if (typeof file !== 'string') throw invalidMarkdown(`${location}.file must be a string`);
114	    if (typeof sha256 !== 'string' || !HEX_SHA256.test(sha256)) {
115	      throw invalidMarkdown(`${location}.sha256 must be a lowercase hex SHA-256`);
116	    }
117	    if (!Array.isArray(tags) || tags.some((tag) => typeof tag !== 'string')) {
118	      throw invalidMarkdown(`${location}.tags must be an array of strings`);
119	    }
120	    if (seenIds.has(id)) throw invalidMarkdown(`duplicate document id: ${id}`);
121	    seenIds.add(id);
122	    if (file !== `${id}.md`) throw invalidMarkdown(`${location}.file must equal ${id}.md`);
123	
124	    const bytes = fileBytes.get(file);
125	    if (bytes === undefined) throw invalidMarkdown(`missing package file: ${file}`);
126	    if (sha256Bytes(bytes) !== sha256) {
127	      throw invalidMarkdown(`sha256 mismatch for ${file}`);
128	    }
129	    let body;
130	    try {
131	      body = fatalDecoder.decode(bytes);
132	    } catch {
133	      throw invalidMarkdown(`illegal UTF-8 in package file: ${file}`);
134	    }
135	    try {
136	      assertDocument({ id, title, body, tags });
137	    } catch (error) {
138	      throw invalidMarkdown(`${location}: ${error.message}`);
139	    }
140	    entries.push({ id, title: title.trim(), body, tags: normalizeTags(tags), file, sha256 });
141	  });
142	
143	  entries.sort((a, b) => compareCodePoints(a.id, b.id));
144	  const titles = new Set();
145	  for (const entry of entries) {
146	    if (titles.has(entry.title)) throw invalidMarkdown(`duplicate normalized title: ${entry.title}`);
147	    titles.add(entry.title);
148	  }
149	
150	  const expectedFiles = new Set([MANIFEST_FILE, ...entries.map((entry) => entry.file)]);
151	  for (const name of fileBytes.keys()) {
152	    if (!expectedFiles.has(name)) throw invalidMarkdown(`unexpected package file: ${name}`);
153	  }
154	  return { entries, checksum };
155	}
