159	// Resolves symlinks of every existing path component, appending a nonexistent
160	// tail lexically, so aliased paths compare by their real on-disk location.
161	function realLocation(target) {
162	  let current = path.resolve(target);
163	  const tail = [];
164	  for (;;) {
165	    try {
166	      const real = fs.realpathSync(current);
167	      return tail.length === 0 ? real : path.join(real, ...tail.reverse());
168	    } catch (error) {
169	      if (error.code !== 'ENOENT' && error.code !== 'ENOTDIR') {
170	        throw ioError(`cannot resolve ${target}: ${error.message}`);
171	      }
172	      tail.push(path.basename(current));
173	      const parent = path.dirname(current);
174	      if (parent === current) return current;
175	      current = parent;
176	    }
177	  }
178	}
179	
180	function isInside(candidate, directory) {
181	  const relative = path.relative(directory, candidate);
182	  return relative === '' || (!relative.startsWith('..') && !path.isAbsolute(relative));
183	}
184	
185	// ---- File-system orchestration --------------------------------------------
186	
187	function readSnapshotText(file) {
188	  try {
189	    return fs.readFileSync(file, 'utf8');
190	  } catch (error) {
191	    throw ioError(`cannot read snapshot file ${file}: ${error.message}`);
192	  }
193	}
194	
195	function stagingFile(file) {
196	  const directory = path.dirname(path.resolve(file));
197	  return path.join(directory, `.${path.basename(file)}.${process.pid}.tmp`);
198	}
199	
200	function atomicWrite(file, content) {
201	  const temp = stagingFile(file);
202	  try {
203	    fs.writeFileSync(temp, content, 'utf8');
204	    fs.renameSync(temp, file);
205	  } catch (error) {
206	    try {
207	      fs.rmSync(temp, { force: true });
208	    } catch {
209	      // best-effort staging cleanup
210	    }
211	    throw ioError(`cannot write snapshot file ${file}: ${error.message}`);
212	  }
213	}
214	
215	// Enforces the package directory's structural rules and returns its parsed
216	// contents. The directory itself must be a real directory (not a symlink);
217	// it may contain only regular files with legal names — no symlinks,
218	// subdirectories, devices, or other special entries.
219	function readPackageDirectory(directory) {
220	  let rootStats;
221	  try {
222	    rootStats = fs.lstatSync(directory);
223	  } catch (error) {
224	    throw ioError(`cannot read package directory ${directory}: ${error.message}`);
225	  }
226	  if (rootStats.isSymbolicLink()) throw invalidMarkdown('package directory must not be a symlink');
227	  if (!rootStats.isDirectory()) throw ioError(`package input is not a directory: ${directory}`);
228	
229	  let names;
230	  try {
231	    names = fs.readdirSync(directory);
232	  } catch (error) {
233	    throw ioError(`cannot read package directory ${directory}: ${error.message}`);
234	  }
235	  if (!names.includes(MANIFEST_FILE)) throw invalidMarkdown(`missing package file: ${MANIFEST_FILE}`);
236	
237	  const fileBytes = new Map();
238	  for (const name of names) {
239	    if (name === '' || name === '.' || name === '..' || name.includes('/') || name.includes('\\')) {
240	      throw invalidMarkdown(`illegal package file name: ${name}`);
241	    }
242	    const full = path.join(directory, name);
243	    let stats;
244	    try {
245	      stats = fs.lstatSync(full);
246	    } catch (error) {
247	      throw ioError(`cannot read package file ${name}: ${error.message}`);
248	    }
249	    if (stats.isSymbolicLink()) throw invalidMarkdown(`symlinks are not allowed in a package: ${name}`);
250	    if (stats.isDirectory()) throw invalidMarkdown(`subdirectories are not allowed in a package: ${name}`);
251	    if (!stats.isFile()) throw invalidMarkdown(`illegal package entry: ${name}`);
252	    try {
253	      fileBytes.set(name, fs.readFileSync(full));
254	    } catch (error) {
255	      throw ioError(`cannot read package file ${name}: ${error.message}`);
256	    }
257	  }
258	
259	  let manifestRaw;
260	  try {
261	    manifestRaw = JSON.parse(fileBytes.get(MANIFEST_FILE).toString('utf8'));
262	  } catch {
263	    throw invalidMarkdown('manifest is not valid JSON');
264	  }
265	  return parsePackage(manifestRaw, fileBytes);
266	}
267	
268	function removeQuiet(target) {
269	  try {
270	    fs.rmSync(target, { recursive: true, force: true });
271	  } catch {
272	    // best-effort cleanup
273	  }
274	}
275	
276	// Exports a version-1 JSON snapshot file into a Markdown package directory.
277	// The package is materialized in a sibling staging directory and swapped into
278	// place with a single rename; fixed staging/backup names let a retry after a
279	// killed export finish a complete package with no stale files left behind.
280	export function exportMarkdown(snapshotFile, outputDirectory) {
281	  const output = path.resolve(outputDirectory);
282	  const parent = path.dirname(output);
283	  let parentStats;
284	  try {
285	    // Follow symlinked ancestors: only the target leaf itself being a symlink
286	    // is rejected below.
287	    parentStats = fs.statSync(parent);
288	  } catch (error) {
289	    throw ioError(`cannot access output parent ${parent}: ${error.message}`);
290	  }
291	  if (!parentStats.isDirectory()) throw ioError(`output parent is not a directory: ${parent}`);
292	
293	  let outputStats;
294	  try {
295	    outputStats = fs.lstatSync(output);
296	  } catch (error) {
297	    if (error.code !== 'ENOENT') throw ioError(`cannot access output directory ${outputDirectory}: ${error.message}`);
298	  }
299	  if (outputStats?.isSymbolicLink()) {
300	    throw new SnapshotError('INVALID_OPTIONS', 'output directory must not be a symlink');
301	  }
302	
303	  // Fixed staging/backup names used below. They are computed before any check
304	  // so the source can be protected against all three locations the export
305	  // replaces or removes — not just the final output directory.
306	  const stage = `${output}.export.tmp`;
307	  const backup = `${output}.old.tmp`;
308	
309	  // Path-option checks precede reading so an invalid layout is reported even
310	  // when the source itself would be unreadable. The source snapshot is user
311	  // input: it must never be deleted, moved, or rewritten merely because it
312	  // sits at (or inside) the output directory or either scratch location this
313	  // export is about to clear or swap. All comparisons use real locations so
314	  // paths reached through symlinked parents alias correctly even when the
315	  // output leaf does not exist yet.
316	  const sourceReal = realLocation(snapshotFile);
317	  const protectedLocations = [realLocation(output), realLocation(stage), realLocation(backup)];
318	  if (protectedLocations.some((location) => isInside(sourceReal, location))) {
319	    throw new SnapshotError(
320	      'INVALID_OPTIONS',
321	      'source snapshot must not be the output directory or an export staging or backup location',
322	    );
323	  }
324	
325	  const snapshotText = readSnapshotText(snapshotFile);
326	
327	  // All content validation happens before anything on disk changes.
328	  const workspace = new Workspace();
329	  workspace.importJSON(snapshotText, { mode: 'replace' });
330	  const snapshot = workspace.exportJSON();
331	  const { files, manifestText } = buildPackage(snapshot);
332	
333	  // Clear leftovers from a previously killed attempt first.
334	  removeQuiet(stage);
335	  removeQuiet(backup);
336	  let stageReady = false;
337	  try {
338	    fs.mkdirSync(stage);
339	    for (const [name, bytes] of files) fs.writeFileSync(path.join(stage, name), bytes);
340	    stageReady = true;
341	
342	    const hadTarget = outputStats !== undefined;
343	    if (hadTarget) fs.renameSync(output, backup);
344	    try {
345	      fs.renameSync(stage, output);
346	    } catch (error) {
347	      if (hadTarget) {
348	        try {
349	          fs.renameSync(backup, output);
350	        } catch {
351	          // surface the original failure with whatever can be restored
352	        }
353	      }
354	      throw error;
355	    }
356	    if (hadTarget) removeQuiet(backup);
357	  } catch (error) {
358	    if (stageReady) removeQuiet(stage);
359	    if (error instanceof SnapshotError) throw error;
360	    throw ioError(`cannot write package directory ${outputDirectory}: ${error.message}`);
361	  }
362	
363	  return { manifest: JSON.parse(manifestText), manifestText };
364	}
365	
366	// Imports a Markdown package over a base snapshot and writes the projected
367	// version-1 snapshot. Every validation step runs before the output is
368	// touched, so failure leaves the base snapshot and any existing output
369	// untouched. Returns the result snapshot plus the exact bytes saved.
370	export function importMarkdown(baseFile, inputDirectory, outputFile, mode, dryRun = false) {
371	  const input = path.resolve(inputDirectory);
372	  let inputStats;
373	  try {
374	    inputStats = fs.lstatSync(input);
375	  } catch (error) {
376	    throw ioError(`cannot read package directory ${inputDirectory}: ${error.message}`);
377	  }
378	  if (inputStats.isSymbolicLink()) throw invalidMarkdown('package directory must not be a symlink');
379	
380	  // Layout options are validated before any file content is read.
381	  const inputReal = realLocation(input);
382	  const outputReal = realLocation(outputFile);
383	  if (isInside(outputReal, inputReal)) {
384	    throw new SnapshotError('INVALID_OPTIONS', 'output snapshot must not be inside the input package');
385	  }
386	
387	  const baseText = readSnapshotText(baseFile);
388	  const { entries, checksum } = readPackageDirectory(input);
389	
390	  const baseWorkspace = new Workspace();
391	  baseWorkspace.importJSON(baseText, { mode: 'replace' });
392	
393	  // Rebuild the incoming snapshot from normalized entries and verify the
394	  // manifest's bound checksum exactly as a version-1 snapshot would compute.
395	  const incomingDocuments = entries.map(({ file: _file, sha256: _sha256, ...document }) => structuredClone(document));
396	  const incomingWorkspace = new Workspace();
397	  try {
398	    incomingWorkspace.importJSON(
399	      { version: 1, documents: incomingDocuments, checksum },
400	      { mode: 'replace' },
401	    );
402	  } catch (error) {
403	    if (error instanceof SnapshotError && error.code === 'INVALID_SNAPSHOT') {
404	      throw invalidMarkdown(`package does not rebuild a matching snapshot: ${error.message}`);
405	    }
406	    throw error;
407	  }
408	  const incomingSnapshot = incomingWorkspace.exportJSON();
409	  if (incomingSnapshot.checksum !== checksum) {
410	    throw invalidMarkdown('manifest checksum does not match the rebuilt snapshot');
411	  }
412	
413	  // Existing merge conflict / ids rules apply unchanged; replace installs
414	  // the package wholesale.
415	  const result = baseWorkspace.importJSON(incomingSnapshot, { mode });
416	
417	  const rendered = `${JSON.stringify(result)}\n`;
418	  if (!dryRun) atomicWrite(path.resolve(outputFile), rendered);
419	  return { snapshot: result, rendered: dryRun ? null : rendered };
420	}
