292	test('export refuses a source inside the staging or backup location and changes nothing', () => {
293	  const snapshotTree = (root) => {
294	    const walk = (directory) => {
295	      const entries = {};
296	      for (const name of fs.readdirSync(directory).sort()) {
297	        const full = path.join(directory, name);
298	        const stats = fs.lstatSync(full);
299	        if (stats.isSymbolicLink()) entries[name] = `<symlink:${fs.readlinkSync(full)}>`;
300	        else if (stats.isDirectory()) entries[name] = walk(full);
301	        else entries[name] = fs.readFileSync(full);
302	      }
303	      return entries;
304	    };
305	    return walk(root);
306	  };
307	
308	  const variants = [
309	    (dir) => {
310	      // Leftover staging directory from a killed previous export.
311	      const stage = path.join(dir, 'pkg.export.tmp');
312	      fs.mkdirSync(stage);
313	      fs.writeFileSync(path.join(stage, 'partial.md'), 'partial');
314	      fs.writeFileSync(path.join(stage, 'snap.json'), fs.readFileSync(path.join(dir, 'snap.json')));
315	      return { source: path.join(stage, 'snap.json'), output: path.join(dir, 'pkg') };
316	    },
317	    (dir) => {
318	      // Leftover backup directory holding the source snapshot.
319	      const backup = path.join(dir, 'pkg.old.tmp');
320	      fs.mkdirSync(backup);
321	      fs.writeFileSync(path.join(backup, 'snap.json'), fs.readFileSync(path.join(dir, 'snap.json')));
322	      return { source: path.join(backup, 'snap.json'), output: path.join(dir, 'pkg') };
323	    },
324	    (dir) => {
325	      // The scratch location itself is the snapshot file (exact equality).
326	      const stage = path.join(dir, 'pkg.export.tmp');
327	      fs.writeFileSync(stage, fs.readFileSync(path.join(dir, 'snap.json')));
328	      return { source: stage, output: path.join(dir, 'pkg') };
329	    },
330	  ];
331	  for (let index = 0; index < variants.length; index += 1) {
332	    const cwd = tempDir();
333	    writeSnapshot(path.join(cwd, 'snap.json'), workspaceWith([{ id: 'a', title: 'A', body: 'b', tags: [] }]));
334	    // A pre-existing target with content the rejection must leave in place.
335	    fs.mkdirSync(path.join(cwd, 'pkg'));
336	    fs.writeFileSync(path.join(cwd, 'pkg', 'untouched'), 'yes');
337	
338	    const { source, output } = variants[index](cwd);
339	    const before = snapshotTree(cwd);
340	    assert.throws(
341	      () => exportMarkdown(source, output),
342	      (error) => error.code === 'INVALID_OPTIONS',
343	      `variant ${index}`,
344	    );
345	    // No path under cwd was deleted, moved, created, or rewritten.
346	    assert.deepEqual(snapshotTree(cwd), before, `variant ${index}`);
347	  }
348	});
